        int idx1 = start;
        int idx2 = start + len - 1;
        while ((idx1 <= idx2) && (!Character.isLetterOrDigit(array[idx1]))) {
            idx1++;
        }
        while ((idx1 <= idx2) && (!Character.isLetterOrDigit(array[idx2]))) {
